-- ============================================================================
-- REFRESH MEMOS — self-referencing lookups (see 02-create-functions.sql)
-- Generated by rulebook-to-postgres tool. Runs after the seed data. Each round
-- memoises the rows whose self-referenced parents are already memoised, so every
-- __compute call reads its parents from the memo. Rows on a genuine row cycle are
-- never ready and stay unmemoised (their wrapper falls back to __compute).
-- ============================================================================

CREATE OR REPLACE FUNCTION erb_refresh_memo_jurisdictions() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_jurisdictions_name;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.jurisdiction_id::text FROM jurisdictions c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_jurisdictions_name m WHERE m.id = c.jurisdiction_id::text)
      AND (c.parent_jurisdiction IS NULL OR NOT EXISTS (SELECT 1 FROM jurisdictions p WHERE p.jurisdiction_id = c.parent_jurisdiction) OR EXISTS (SELECT 1 FROM erb_memo_jurisdictions_name m WHERE m.id = c.parent_jurisdiction::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_jurisdictions_name(id, val) SELECT c.jurisdiction_id::text, calc_jurisdictions_name__compute(c.jurisdiction_id) FROM jurisdictions c JOIN erb_memo_round r ON r.id = c.jurisdiction_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memos() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM erb_refresh_memo_jurisdictions();
END $$;

SELECT erb_refresh_memos();
